; Bookshelf targets, enemy state and artwork.
; Original DS:37A3..3B02 (end exclusive).

; DS:37a3 bookshelf_target_x: 3 x 2 bytes.
; CS:3B51..3B62 scans offsets 4,2,0 and reads target X.
data_37a3: dw 0x00c0, 0x00e0, 0x0100
; DS:37a9 bookshelf_target_video_offsets: 3 x 2 bytes.
; CS:3BB9 selects the erased target CGA address using offsets 0,2,4.
data_37a9: dw 0x03f0, 0x03f8, 0x0400
; DS:37af bookshelf_targets_remaining: 1 bytes.
; 3B30 initializes three; 3BA3 decrements after removal.
data_37af: db 0x00
; DS:37b0 bookshelf_target_active: 3 x 2 bytes.
; CS:3B38..3B3E sets three words to one; CS:3BA3 clears the contacted slot.
data_37b0: dw 0x0000, 0x0000, 0x0000
; DS:37b6 bookshelf_target_byte_offset: 1 x 2 bytes.
; CS:3B51 starts at four; CS:3B9B subtracts two to scan three word slots.
data_37b6: dw 0x0000
; DS:37b8 bookshelf_targets_last_tick: 1 x 2 bytes.
; CS:3B46/3B4D gates target contacts by BIOS tick.
data_37b8: dw 0x0000
